insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-09-29','nieuw','Planning','Voortgang bijwerken vanaf je telefoon',
   'Heb je een rol op een project, dan kun je in de app op het tabblad Voortgang per bewakingscode invullen hoeveel van het arbeidswerk klaar is. EVA rekent dat om naar het totale % gereed van die code, dus op kantoor zie je meteen de nieuwe stand. Het % gereed wijzigen kan voortaan alleen nog door wie een rol op het project heeft.'),
  ('2026-09-29','verbeterd','Dossiers','In de app zie je de dossiers waarop je bent ingepland',
   'De dossierlijst in de app toont nu ook de projecten waarop je in de planning staat, ook als je er geen rol op hebt. Servicedeskbonnen die uitgevoerd of kosten compleet zijn verdwijnen uit de lijst, zodat je alleen ziet waar je nog mee bezig bent.');
